#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-08

# strict-mode: opt-out a fault-arm probe must OBSERVE non-zero gate exits, not
# die on them, so it runs `set -uo pipefail` without -e like every other probe
# under tests/*/fault-arms/.
#
# Gate: tests/plugins/test-pi-plugin.sh
#
# Pass condition: exit 0. The bug this gate exists for is an ABSENT manifest
# that raises no error (`pi install` registered 0 resources and said nothing),
# so the arms below remove one input at a time and the gate must go red each
# time. fault3 is the subtler one: the manifest is present and well formed but
# resolves to fewer skills than the tree holds, which is what a build drift or a
# renamed skills directory looks like.
set -uo pipefail

REPO="${REPO:?set by the fault-arms runner}"
GATE="$REPO/tests/plugins/test-pi-plugin.sh"
FIX="$H/fixtures/pi-plugin"

rm -rf "$FIX"

write_skill() {
  local path="$1" name="$2"
  mkdir -p "$(dirname "$path")"
  {
    echo "---"
    echo "name: $name"
    echo "description: Fixture skill for the pi adapter fault arms."
    echo "---"
    echo
    echo "# $name"
  } >"$path"
}

build_tree() {
  local dir="$1"
  mkdir -p "$dir/.pi" "$dir/tests/agents"
  write_skill "$dir/src/skills/alpha/SKILL.md" alpha
  write_skill "$dir/src/skills/beta/SKILL.md" beta
  write_skill "$dir/plugins/ork/skills/alpha/SKILL.md" alpha
  write_skill "$dir/plugins/ork/skills/beta/SKILL.md" beta
  # The stray non-skill markdown the real tree also carries, so the fixture
  # exercises the exclude pattern rather than a tidier shape than production.
  echo "# Contributing" >"$dir/plugins/ork/skills/CONTRIBUTING-SKILLS.md"
  cp "$REPO/.pi/mcp.json.example" "$dir/.pi/mcp.json.example"
  cp "$REPO/tests/agents/mcp-servers.manifest.json" "$dir/tests/agents/mcp-servers.manifest.json"
  printf '.pi/mcp.json\n' >"$dir/.gitignore"
  git -C "$dir" init -q
}

write_pkg() {
  local dir="$1" skills="$2"
  printf '{\n  "name": "fixture",\n  "version": "0.0.0",\n  "pi": {\n    "skills": %s\n  }\n}\n' \
    "$skills" >"$dir/package.json"
}

SOURCES='["./plugins/ork/skills", "-plugins/ork/skills/CONTRIBUTING-SKILLS.md"]'

# control: the shipped shape.
build_tree "$FIX/control"
write_pkg "$FIX/control" "$SOURCES"

# fault: no `pi` key at all. This is the pre-#4001 state of the repo.
build_tree "$FIX/fault"
printf '{\n  "name": "fixture",\n  "version": "0.0.0"\n}\n' >"$FIX/fault/package.json"

# fault2: manifest present, MCP allowlist template gone.
build_tree "$FIX/fault2"
write_pkg "$FIX/fault2" "$SOURCES"
rm -f "$FIX/fault2/.pi/mcp.json.example"

# fault3: manifest present and well formed, but it resolves to 1 of the 2
# skills in the tree. A partial registration is silent in pi.
build_tree "$FIX/fault3"
write_pkg "$FIX/fault3" '["./plugins/ork/skills/alpha"]'

run_arm() {
  CLAUDE_PROJECT_DIR="$1" bash "$GATE" >"$2" 2>&1
}

run_arm "$FIX/control" "$FIX/control.log"; control_rc=$?
run_arm "$FIX/fault" "$FIX/fault.log"; fault_rc=$?
run_arm "$FIX/fault2" "$FIX/fault2.log"; fault2_rc=$?
run_arm "$FIX/fault3" "$FIX/fault3.log"; fault3_rc=$?

{
  echo "--- control tail ---"; tail -3 "$FIX/control.log"
  echo "--- fault tail ---";   tail -3 "$FIX/fault.log"
  echo "--- fault2 tail ---";  tail -3 "$FIX/fault2.log"
  echo "--- fault3 tail ---";  tail -3 "$FIX/fault3.log"
} >&2

printf 'RESULT gate=%s control=%s fault=%s fault2=%s fault3=%s\n' \
  "pi-plugin" "$control_rc" "$fault_rc" "$fault2_rc" "$fault3_rc"
